public bool CanFinish(int n, int[][] prerequisites) {
    var next = new List<int>[n];
    var indegree = new int[n];
    for (int i = 0; i < n; i++) next[i] = new List<int>();
    foreach (var p in prerequisites) { next[p[1]].Add(p[0]); indegree[p[0]]++; }
    var queue = new Queue<int>();
    for (int i = 0; i < n; i++) if (indegree[i] == 0) queue.Enqueue(i);
    int taken = 0;
    while (queue.Count > 0) {
        int c = queue.Dequeue();
        taken++;
        foreach (int d in next[c])
            if (--indegree[d] == 0) queue.Enqueue(d);   // its last prerequisite is done
    }
    return taken == n;                                    // the leftovers are stuck in a cycle
}

