// 0 — not visited, 1 — on the current path, 2 — fully explored
bool HasCycle(int v, List<int>[] next, int[] state) {
    state[v] = 1;
    foreach (int d in next[v]) {
        if (state[d] == 1) return true;                    // back onto our own path
        if (state[d] == 0 && HasCycle(d, next, state)) return true;
    }
    state[v] = 2;                                          // no cycle from v — never enter again
    return false;
}
