public Node CloneGraph(Node node) {
    if (node == null) return null;
    var copy = new Dictionary<Node, Node> { [node] = new Node(node.val) };
    var queue = new Queue<Node>();
    queue.Enqueue(node);
    while (queue.Count > 0) {
        var cur = queue.Dequeue();
        foreach (var nb in cur.neighbors) {
            if (!copy.ContainsKey(nb)) {           // first meeting: create a copy and schedule it
                copy[nb] = new Node(nb.val);
                queue.Enqueue(nb);
            }
            copy[cur].neighbors.Add(copy[nb]);    // the copy's edge points to the neighbor's copy
        }
    }
    return copy[node];
}
